action:
$de = strncmp(IPS_GetSystemLanguage(), 'de', 2) == 0;
$description = json_decode((string) @HM_GetParamsetDescription($_IPS['TARGET']), true);
if (!is_array($description) || !isset($description['ALL_LEDS'])) {
    echo $de ? 'Das Ziel hat keine Funktion zum Setzen aller LEDs.' : 'This target has no function to set all LEDs.';
    return;
}
$address = (string) IPS_GetProperty($_IPS['TARGET'], 'Address');
$device = (string) substr($address, 0, (int) strpos($address, ':'));
$channels = [];
foreach (IPS_GetInstanceListByModuleID('{EE4A81C6-5C90-4DB7-AD2F-F6BBD521412E}') as $instance) {
    $instanceAddress = (string) IPS_GetProperty($instance, 'Address');
    if (($device !== '') && (strpos($instanceAddress, $device . ':') === 0) && (@IPS_GetObjectIDByIdent('LED_STATUS', $instance) !== false)) {
        $channels[(int) substr($instanceAddress, strlen($device) + 1)] = $instance;
    }
}
$value = 0;
for ($led = 1; $led <= 16; $led++) {
    $color = (int) $_IPS['LED' . $led];
    if ($color == 4) {
        // Unverändert: aktuellen Zustand der LED von der CCU lesen (Instanz des Kanals)
        if (!isset($channels[$led])) {
            echo $de ? 'Für LED ' . $led . ' gibt es keine Instanz, der Zustand kann nicht beibehalten werden.' : 'There is no instance for LED ' . $led . ', its state cannot be kept.';
            return;
        }
        @HM_RequestStatus($channels[$led], 'LED_STATUS');
        $color = (int) GetValueInteger(IPS_GetObjectIDByIdent('LED_STATUS', $channels[$led]));
    }
    $value |= ($color & 3) << (2 * ($led - 1));
}
HM_WriteValueString($_IPS['TARGET'], 'ALL_LEDS', (string) $value);
